$b$, $b$class Solution:
    def validPalindrome(self, s):
        def pal(i, j):
            while i < j:
                if s[i] != s[j]:
                    return False
                i += 1; j -= 1
            return True
        i, j = 0, len(s) - 1
        while i < j:
            if s[i] != s[j]:
                return pal(i + 1, j) or pal(i, j - 1)
            i += 1; j -= 1
        return True$b$)
