const __res = diameterOfBinaryTree(_a0);
__print(__res);
$b$, $b$var diameterOfBinaryTree = function(root) {
    let best = 0;
    const h = n => { if (!n) return 0; const l = h(n.left), r = h(n.right); best = Math.max(best, l + r); return 1 + Math.max(l, r); };
    h(root);
    return best;
};$b$)
