$b$, $b$class Solution:
    def validWordAbbreviation(self, word, abbr):
        i = j = 0
        while i < len(word) and j < len(abbr):
            if abbr[j].isdigit():
                if abbr[j] == '0':
                    return False
                n = 0
                while j < len(abbr) and abbr[j].isdigit():
                    n = n * 10 + int(abbr[j]); j += 1
                i += n
            else:
                if word[i] != abbr[j]:
                    return False
                i += 1; j += 1
        return i == len(word) and j == len(abbr)$b$)
