$b$, $b$class MyQueue:
    def __init__(self):
        self.inn, self.out = [], []
    def push(self, x):
        self.inn.append(x)
    def _move(self):
        if not self.out:
            while self.inn:
                self.out.append(self.inn.pop())
    def pop(self):
        self._move(); return self.out.pop()
    def peek(self):
        self._move(); return self.out[-1]
    def empty(self):
        return not self.inn and not self.out$b$)
