$b$, $b$class Solution:
    def findAnagrams(self, s, p):
        need, win, out = Counter(p), Counter(), []
        for i, c in enumerate(s):
            win[c] += 1
            if i >= len(p):
                o = s[i - len(p)]
                win[o] -= 1
                if win[o] == 0:
                    del win[o]
            if win == need:
                out.append(i - len(p) + 1)
        return out$b$)
