$b$, $b$var removeNthFromEnd = function(head, n) {
    const nodes = [];
    for (let x = head; x; x = x.next) nodes.push(x);
    const i = nodes.length - n;
    if (i === 0) return head.next;
    nodes[i - 1].next = nodes[i].next;
    return head;
};$b$)
