$b$, $b$class Solution:
    def pathSum(self, root, targetSum):
        seen = Counter({0: 1})
        def dfs(n, acc):
            if not n:
                return 0
            acc += n.val
            r = seen[acc - targetSum]
            seen[acc] += 1
            r += dfs(n.left, acc) + dfs(n.right, acc)
            seen[acc] -= 1
            return r
        return dfs(root, 0)$b$)
