    def numIslands(self, grid):
        m, n, count = len(grid), len(grid[0]), 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == "1":
                    count += 1
                    st = [(i, j)]; grid[i][j] = "0"
                    while st:
                        a, b = st.pop()
                        for x, y in ((a+1, b), (a-1, b), (a, b+1), (a, b-1)):
