    def cloneGraph(self, node):
        if not node:
            return None
        copies = {}
        def dfs(n):
            if n in copies:
                return copies[n]
            c = copies[n] = Node(n.val)
            c.neighbors = [dfs(x) for x in n.neighbors]
            return c
        return dfs(node)$b$)
