const __res = minMeetingRooms(_a0);
__print(__res);
$b$, $b$var minMeetingRooms = function(intervals) {
    const ev = [];
    for (const [s, e] of intervals) { ev.push([s, 1]); ev.push([e, -1]); }
    ev.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    let cur = 0, best = 0;
    for (const [, d] of ev) { cur += d; best = Math.max(best, cur); }
    return best;
};$b$)
