$b$, $b$class Solution:
    def shortestPathBinaryMatrix(self, grid):
        n = len(grid)
        if grid[0][0] or grid[-1][-1]:
            return -1
        q, dist = deque([(0, 0)]), {(0, 0): 1}
        while q:
            a, b = q.popleft()
            if (a, b) == (n - 1, n - 1):
                return dist[(a, b)]
            for da in (-1, 0, 1):
                for db in (-1, 0, 1):
                    x, y = a + da, b + db
                    if 0 <= x < n and 0 <= y < n and not grid[x][y] and (x, y) not in dist:
                        dist[(x, y)] = dist[(a, b)] + 1; q.append((x, y))
        return -1$b$)
