$b$, $b$class Solution:
    def simplifyPath(self, path):
        st = []
        for part in path.split('/'):
            if part == '..':
                if st:
                    st.pop()
            elif part and part != '.':
                st.append(part)
        return '/' + '/'.join(st)$b$)
