    const g = new Map();
    for (const line of paths) {
        const [d, ...files] = line.split(' ');
        for (const f of files) {
            const i = f.indexOf('('), name = f.slice(0, i), content = f.slice(i + 1, -1);
            if (!g.has(content)) g.set(content, []);
