$b$, $b$class Solution:
    def divide(self, dividend, divisor):
        neg = (dividend < 0) != (divisor < 0)
        a, b, q = abs(dividend), abs(divisor), 0
        while a >= b:
            t, m = b, 1
            while a >= (t << 1):
                t <<= 1; m <<= 1
            a -= t; q += m
        q = -q if neg else q
        return min(max(q, -2**31), 2**31 - 1)$b$)
