$b$, $b$class Solution:
    def averageBelowK(self, root, k):
        total = count = 0
        st = [root]
        while st:
            n = st.pop()
            if not n:
                continue
            if n.val < k:
                total += n.val; count += 1
                st.append(n.left); st.append(n.right)
            else:
                st.append(n.left)
        return total / count if count else 0.0$b$)
