$b$, $b$var averageBelowK = function(root, k) {
    const vals = [];
    const walk = n => { if (!n) return; if (n.val < k) vals.push(n.val); walk(n.left); walk(n.right); };
    walk(root);
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
};$b$)
