$b$, $b$class Solution:
    def kthLargest(self, lists, k):
        h = [(-l[-1], i, len(l) - 1) for i, l in enumerate(lists) if l]
        heapq.heapify(h)
        while True:
            v, i, j = heapq.heappop(h)
            k -= 1
            if k == 0:
                return -v
            if j > 0:
                heapq.heappush(h, (-lists[i][j - 1], i, j - 1))$b$)
