$b$, $b$class Solution:
    def findCheapestPrice(self, n, flights, src, dst, k):
        cost = [float('inf')] * n; cost[src] = 0
        for _ in range(k + 1):
            nxt = cost[:]
            for u, v, p in flights:
                if cost[u] + p < nxt[v]:
                    nxt[v] = cost[u] + p
            cost = nxt
        return -1 if cost[dst] == float('inf') else cost[dst]$b$)
