$b$, $b$class Solution:
    def sortArray(self, nums):
        def qs(a):
            if len(a) <= 1:
                return a
            p = a[random.randrange(len(a))]
            return qs([x for x in a if x < p]) + [x for x in a if x == p] + qs([x for x in a if x > p])
        return qs(nums)$b$)
