$b$, $b$class Solution:
    def findWords(self, board, words):
        trie = {}
        for w in words:
            n = trie
            for c in w:
                n = n.setdefault(c, {})
            n['$'] = w
        m, k, out = len(board), len(board[0]), []
        def dfs(i, j, parent):
            c = board[i][j]; node = parent[c]
            if '$' in node:
                out.append(node.pop('$'))
            board[i][j] = '#'
            for x, y in ((i+1, j), (i-1, j), (i, j+1), (i, j-1)):
                if 0 <= x < m and 0 <= y < k and board[x][y] in node:
                    dfs(x, y, node)
            board[i][j] = c
            if not node:
                parent.pop(c)
        for i in range(m):
            for j in range(k):
                if board[i][j] in trie:
                    dfs(i, j, trie)
        return out$b$)
