$b$, $b$class Solution:
    def trap(self, height):
        i, j, lm, rm, water = 0, len(height) - 1, 0, 0, 0
        while i < j:
            if height[i] < height[j]:
                lm = max(lm, height[i]); water += lm - height[i]; i += 1
            else:
                rm = max(rm, height[j]); water += rm - height[j]; j -= 1
        return water$b$)
