$b$, $b$class Codec:
    def serialize(self, root):
        out = []
        def go(n):
            if not n:
                out.append('#'); return
            out.append(str(n.val)); go(n.left); go(n.right)
        go(root)
        return ' '.join(out)
    def deserialize(self, data):
        it = iter(data.split())
        def go():
            v = next(it)
            if v == '#':
                return None
            n = TreeNode(int(v)); n.left = go(); n.right = go()
            return n
        return go()$b$)
