$b$, $b$class Solution:
    def solveNQueens(self, n):
        out, cols = [], []
        def go(r, used, d1, d2):
            if r == n:
                out.append(['.' * c + 'Q' + '.' * (n - c - 1) for c in cols]); return
            for c in range(n):
                if c not in used and r - c not in d1 and r + c not in d2:
                    cols.append(c)
                    go(r + 1, used | {c}, d1 | {r - c}, d2 | {r + c})
                    cols.pop()
        go(0, set(), set(), set())
        return out$b$)
