$b$, $b$class Solution:
    def mergeKLists(self, lists):
        h = [(n.val, i, n) for i, n in enumerate(lists) if n]
        heapq.heapify(h)
        dummy = cur = ListNode()
        while h:
            v, i, n = heapq.heappop(h)
            cur.next = n; cur = n
